SELECT * FROM ( select a.*,ROW_NUMBER() OVER (ORDER BY num) AS rownum,FORMAT(wdate, 'yyyy-MM-dd') AS formatted_date from KCC_EGIS.egis.TBL_NEWS a where 1=1 and a.part = 'movie'
and (a.subject like CONCAT('%', #{searchKeyword}, '%') or a.keyword_tag like CONCAT('%', #{searchKeyword}, '%'))
and a.wtype = #{wtype}
and CONVERT(char(10),a.wdate,23) BETWEEN #{sdate} AND #{edate}
) A
ORDER BY num desc
ORDER BY ${otype} DESC

select count(*) from (select a.* from KCC_EGIS.egis.TBL_NEWS a
where 1=1
and a.part = 'movie'


		and (a.subject like CONCAT('%', #{searchKeyword}, '%') or a.keyword_tag like CONCAT('%', #{searchKeyword}, '%'))




		and a.wtype = #{wtype}




		and CONVERT(char(10),a.wdate,23) BETWEEN #{sdate} AND #{edate}


) A
